import{_ as P,a0 as s,w as a,s as i,I as r,x as e,a1 as n,A as o,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"NMAP 常用掃描簡介（一） | LCTT x X-CMD","titleTemplate":false,"description":"NMAP 常用掃描簡介（一） | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NMAP 常用掃描簡介（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NMAP 常用掃描簡介（一） | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170111 NMAP Common Scans – Part One","title":"NMAP 常用掃描簡介（一）","tag":"201703","desc":""},"relativePath":"201703/20170111 NMAP Common Scans – Part One.md","filePath":"[post].md"}'),l={name:"201703/20170111 NMAP Common Scans – Part One.md"};function d(u,t,I,N,g,f){const p=s("Link");return a(),i("div",null,[t[16]||(t[16]=r("h1",{id:"nmap-常用掃描簡介-一",tabindex:"-1"},[e("NMAP 常用掃描簡介（一） "),r("a",{class:"header-anchor",href:"#nmap-常用掃描簡介-一","aria-label":"Permalink to “NMAP 常用掃描簡介（一）”"},"​")],-1)),r("p",null,[t[1]||(t[1]=e("我們之前在 ",-1)),n(p,{href:"https://www.linuxforum.com/threads/nmap-installation.3431/"},{default:o(()=>[...t[0]||(t[0]=[e("NMAP 的安裝",-1)])]),_:1}),t[2]||(t[2]=e("一文中，列出了 10 種不同的 ZeNMAP 掃描模式。大多數的模式使用了各種參數。各種參數代表了執行不同的掃描模式。這篇文章將介紹其中的四種通用的掃描類型。",-1))]),t[17]||(t[17]=m('<h3 id="四種通用掃描類型" tabindex="-1">四種通用掃描類型 <a class="header-anchor" href="#四種通用掃描類型" aria-label="Permalink to “四種通用掃描類型”">​</a></h3><p>下面列出了最常使用的四種掃描類型：</p><ol><li>PING 掃描 (<code>-sP</code>)</li><li>TCP SYN 掃描 (<code>-sS</code>)</li><li>TCP Connect() 掃描 (<code>-sT</code>)</li><li>UDP 掃描 (<code>-sU</code>)</li></ol><p>當我們利用 NMAP 來執行掃描的時候，這四種掃描類型是我們需要熟練掌握的。更重要的是需要知道這些命令做了什麼並且需要知道這些命令是怎麼做的。本文將介紹 PING 掃描和 UDP 掃描。在之後的文中會介紹 TCP 掃描。</p><h3 id="ping-掃描-sp" tabindex="-1">PING 掃描 (-sP) <a class="header-anchor" href="#ping-掃描-sp" aria-label="Permalink to “PING 掃描 (-sP)”">​</a></h3><p>某些掃描會造成網絡擁塞，然而 Ping 掃描在網絡中最多隻會產生兩個包。當然這兩個包不包括可能需要的 DNS 搜索和 ARP 請求。每個被掃描的 IP 最少只需要一個包來完成 Ping 掃描。</p><p>通常 Ping 掃描是用來查看在指定的 IP 地址上是否有在線的主機存在。例如，當我擁有網絡連接卻連不上一台指定的網絡服務器的時候，我就可以使用 PING 來判斷這台服務器是否在線。PING 同樣也可以用來驗證我的當前設備與網絡服務器之間的路由是否正常。</p><p><strong>注意:</strong> 當我們討論 TCP/IP 的時候，相關信息在使用 TCP/IP 協議的互聯網與局域網（LAN）中都是相當有用的。這些程序都能工作。同樣在廣域網（WAN）也能工作得相當好。</p><p>當參數給出的是一個域名的時候，我們就需要域名解析服務來找到相對應的 IP 地址，這個時候將會生成一些額外的包。例如，當我們執行 <code>ping linuxforum.com</code> 的時候，需要首先請求域名（linuxforum.com）的 IP 地址（98.124.199.63)。當我們執行 <code>ping 98.124.199.63</code> 的時候 DNS 查詢就不需要了。當 MAC 地址未知的時候，就需要發送 ARP 請求來獲取指定 IP 地址的 MAC 地址了（LCTT 譯註：這裏的指定 IP 地址，未必是目的 IP）。</p><p>Ping 命令會向指定的 IP 地址發送一個英特網信息控制協議（ICMP）包。這個包是需要響應的 ICMP Echo 請求。當服務器系統在線的狀態下我們會得到一個響應包。當兩個系統之間存在防火牆的時候，PING 請求包可能會被防火牆丟棄。一些服務器也會被配置成不響應 PING 請求來避免可能發生的死亡之 PING。（LCTT 譯註：現在的操作系統似乎不太可能）</p><p><strong>注意:</strong> 死亡之 PING 是一種惡意構造的 PING 包當它被髮送到系統的時候，會造成被打開的連接等待一個 rest 包。一旦有一堆這樣的惡意請求被系統響應，由於所有的可用連接都已經被打開，所以系統將會拒絕所有其它的連接。技術上來説這種狀態下的系統就是不可達的。</p><p>當系統收到 ICMP Echo 請求後它將會返回一個 ICMP Echo 響應。當源系統收到 ICMP Echo 響應後我們就能知道目的系統是在線可達的。</p><p>使用 NMAP 的時候你可以指定單個 IP 地址也可以指定某個 IP 地址段。當被指定為 PING 掃描（<code>-sP</code>）的時候，會對每一個 IP 地址執行 PING 命令。</p><p>在圖 1 中你可以看到我執行 <code>nmap -sP 10.0.0.1-10</code> 命令後的結果。程序會試着聯繫 IP 地址 10.0.0.1 到 10.0.0.10 之間的每個系統。對每個 IP 地址都要發出三個 ARP 請求。在我們的例子中發出了三十個請求，這 10 個 IP 地址裏面有兩個有回應。（LCTT 譯註：此處原文存疑。）</p><p><img src="https://www.linuxforum.com/attachments/figure-01-jpg.105/" alt="Figure 01"></p><p><em>圖 1</em></p><p>圖 2 中展示了網絡上另一台計算機利用 Wireshark 抓取的發出的請求——沒錯，是在 Windows 系統下完成這次抓取的。第一行展示了發出的第一條請求，廣播請求的是 IP 地址 10.0.0.2 對應 MAC 地址。由於 NMAP 是在 10.0.0.1 這台機器上執行的，因此 10.0.0.1 被略過了。由於本機 IP 地址被略過，我們現在可以看到總共只發出了 27 個 ARP 請求。第二行展示了 10.0.0.2 這台機器的 ARP 響應。第三行到第十行是其它八個 IP 地址的 ARP 請求。第十一行是由於 10.0.0.2 沒有收到請求系統（10.0.0.1）的反饋所以（重新）發送的另一個 ARP 響應。第十二行是源系統向 10.0.0.2 發起的 HTTP 連接的 ‘SYN’ 和 Sequence 0。第十三行和第十四行的兩次 Restart（RST）和 Synchronize（SYN）響應是用來關閉（和重發）第十二行所打開的連接的。注意 Sequence ID 是 ‘1’ - 是源 Sequence ID + 1。第十五行開始就是類似相同的內容。（LCTT 譯註：此處原文有誤，根據情況已經修改。）</p><p><img src="https://www.linuxforum.com/attachments/figure-02-jpg.106/" alt="Figure 02.jpg"></p><p><em>圖 2</em></p><p>回到圖 1 中我們可以看到有兩台主機在線。其中一台是本機（10.0.0.1）另一台是（10.0.0.2）。整個掃描花費了 14.40 秒。</p><p>PING 掃描是一種用來發現在線主機的快速掃描方式。掃描結果中沒有關於網絡、系統的其它信息。這是一種較好的初步發現網絡上在線主機的方式，接着你就可以針對在線系統執行更加複雜的掃描了。你可能還會發現一些不應該出現在網絡上的系統。出現在網絡上的流氓軟件是很危險的，他們可以很輕易的收集內網信息和相關的系統信息。</p><p>一旦你獲得了在線系統的列表，你就可以使用 UDP 掃描來查看哪些端口是可能開啓了的。</p><h3 id="udp-掃描-su" tabindex="-1">UDP 掃描 (-sU) <a class="header-anchor" href="#udp-掃描-su" aria-label="Permalink to “UDP 掃描 (-sU)”">​</a></h3><p>現在你已經知道了有那些系統是在線的，你的掃描就可以聚焦在這些 IP 地址之上。在整個網絡上執行大量的沒有針對性的掃描活動可不是一個好主意，系統管理員可以使用程序來監控網絡流量當有大量異常活動發生的時候就會觸發警報。</p><p>用户數據報協議（UDP）在發現在線系統的開放端口方面十分有用。由於 UDP 不是一個面向連接的協議，因此是不需要響應的。這種掃描方式可以向指定的端口發送一個 UDP 包。如果目標系統沒有回應那麼這個端口可能是關閉的也可能是被過濾了的。如果端口是開放狀態的那麼應該會有一個響應。在大多數的情況下目標系統會返回一個 ICMP 信息説端口不可達。ICMP 信息讓 NMAP 知道端口是被關閉了。如果端口是開啓的狀態那麼目標系統應該響應 ICMP 信息來告知 NMAP 端口可達。</p><p>**注意: **只有最前面的 1024 個常用端口會被掃描。（LCTT 譯註：這裏將 1000 改成了1024，因為手冊中寫的是默認掃描 1 到 1024 端口）在後面的文章中我們會介紹如何進行深度掃描。</p><p>由於我知道 10.0.0.2 這個主機是在線的，因此我只會針對這個 IP 地址來執行掃描。掃描過程中總共收發了 3278 個包。<code>sudo nmap -sU 10.0.0.2</code> 這個命令的輸出結果在圖 3 中展現。</p><p><img src="https://www.linuxforum.com/attachments/figure-03-jpg.107/" alt="Figure 03.jpg"></p><p><em>圖 3</em></p><p>在這副圖中你可以看見端口 137（netbios-ns）被發現是開放的。在圖 4 中展示了 Wireshark 抓包的結果。不能看到所有抓取的包，但是可以看到一長串的 UDP 包。</p><p><img src="https://www.linuxforum.com/attachments/figure-4-jpg.108/" alt="Figure 4.jpg"></p><p><em>圖 4</em></p><p>如果我把目標系統上的防火牆關閉之後會發生什麼呢？我的結果有那麼一點的不同。NMAP 命令的執行結果在圖 5 中展示。</p><p><img src="https://www.linuxforum.com/attachments/figure-05-png.109/" alt="Figure 05.png"></p><p><em>圖 5</em></p><p><strong>注意:</strong> 當你執行 UDP 掃描的時候是需要 root 權限的。</p><p>會產生大量的包是由於我們使用了 UDP。當 NMAP 發送 UDP 請求時它是不保證數據包會被收到的。因為數據包可能會在中途丟失因此它會多次發送請求。</p><hr>',38)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),n(p,{href:"https://www.linuxforum.com/threads/nmap-common-scans-part-one.3637/"},{default:o(()=>[...t[3]||(t[3]=[e("https://www.linuxforum.com/threads/nmap-common-scans-part-one.3637/",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("作者：",-1)),n(p,{href:"https://www.linuxforum.com/members/jarret.268/"},{default:o(()=>[...t[5]||(t[5]=[e("Jarret",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),n(p,{href:"https://github.com/wcnnbdk1"},{default:o(()=>[...t[6]||(t[6]=[e("wcnnbdk1",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),n(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),n(p,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const M=P(l,[["render",d]]);export{A as __pageData,M as default};
